<?php /** @var array $patterns @var array $pages @var \Core\Security\Csrf $csrf */ ?>
<div class="card"><h2 style="margin-top:0">Save a reusable layout</h2><p class="muted">Capture the visual blocks from an existing page, then apply that structure to any other page without copying content by hand.</p>
<form method="post"><?= $csrf->field() ?><input type="hidden" name="action" value="create"><div class="inline-fields"><div><label>Pattern name</label><input name="name" required placeholder="Service landing page"></div><div><label>Copy blocks from</label><select name="page_id" required><option value="">Choose page</option><?php foreach ($pages as $page): ?><option value="<?= (int) $page['id'] ?>"><?= e($page['title']) ?> · /<?= e($page['slug']) ?></option><?php endforeach; ?></select></div><button class="btn" style="align-self:end">Create pattern</button></div></form></div>
<div class="card"><h2 style="margin-top:0">Pattern library</h2>
<?php if (!$patterns): ?><div class="empty-state">No saved patterns yet.</div><?php else: ?><table><tr><th>Name</th><th>Blocks</th><th>Apply to a page</th><th></th></tr><?php foreach ($patterns as $pattern): $blocks=json_decode((string)$pattern['blocks_json'],true)?:[]; ?><tr><td><strong><?= e($pattern['name']) ?></strong><br><span class="muted"><?= e($pattern['updated_at']) ?></span></td><td><?= count($blocks) ?></td><td><form method="post" class="button-row"><?= $csrf->field() ?><input type="hidden" name="action" value="apply"><input type="hidden" name="pattern_id" value="<?= (int)$pattern['id'] ?>"><select name="page_id" required><option value="">Choose page</option><?php foreach($pages as $page): ?><option value="<?= (int)$page['id'] ?>"><?= e($page['title']) ?></option><?php endforeach; ?></select><button class="btn small">Apply</button></form></td><td><form method="post"><?= $csrf->field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$pattern['id'] ?>"><button class="btn small danger">Delete</button></form></td></tr><?php endforeach; ?></table><?php endif; ?></div>
